//! The catalog of language servers Loom can install.
//!
//! Loom ships no server definitions of its own. The catalog is generated by the
//! language server publication workflow (`scripts/lsp-servers`) and staged beside
//! the application like the language package catalog. It lists *packs*, the
//! pinned archives a server runs from, and *servers*, the ways of starting what a
//! pack contains: the command, the languages served and how to find a project
//! root. Several servers can share a pack. An absent or empty catalog means no
//! servers.
use crate::features::language_service::server_set::{ServerSet, is_server_name};
use serde::Deserialize;
use serde_json::{Value, json};
use std::{
    collections::BTreeMap,
    fs,
    io::Read,
    path::{Path, PathBuf},
    sync::{Arc, OnceLock},
};

const MAX_CATALOG: u64 = 4 * 1024 * 1024;
const MAX_PACKS: usize = 128;
const MAX_SERVERS: usize = 256;
/// Largest archive a pack may be published as.
const MAX_ARCHIVE: u64 = 256 * 1024 * 1024;
const PLATFORMS: [&str; 6] = [
    "windows-x86_64",
    "windows-aarch64",
    "macos-x86_64",
    "macos-aarch64",
    "linux-x86_64",
    "linux-aarch64",
];

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Catalog {
    schema: u32,
    distribution: Distribution,
    #[serde(default)]
    packs: BTreeMap<String, Pack>,
    #[serde(default)]
    servers: BTreeMap<String, Entry>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Distribution {
    repository: String,
}

/// A set of pinned archives, one for each platform it supports (or one for all).
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Pack {
    version: String,
    license: String,
    /// Other packs that must be installed to run this one, as `id@major`.
    #[serde(default)]
    requires: Vec<String>,
    platforms: BTreeMap<String, Archive>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Archive {
    asset: String,
    release: String,
    sha256: String,
    size: u64,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Entry {
    /// The name shown to people.
    name: String,
    pack: String,
    command: String,
    #[serde(default)]
    args: Vec<String>,
    #[serde(default)]
    priority: i32,
    #[serde(default)]
    initialization_options: Option<toml::Value>,
    root: Root,
    languages: Vec<Binding>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Root {
    markers: Vec<String>,
    #[serde(default)]
    strategy: Option<String>,
    fallback: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Binding {
    language: String,
    #[serde(default)]
    variant: Option<String>,
    language_id: String,
}

/// One pinned archive of a pack.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct PackArchive {
    pub version: String,
    pub url: String,
    pub sha256: String,
    pub size: u64,
}

/// How one server of a pack is started.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Launching {
    pub server: String,
    pub command: String,
    pub args: Vec<String>,
    pub options: Option<Value>,
}

/// The catalog's name for the platform this process runs on.
pub(crate) fn platform() -> String {
    let os = match std::env::consts::OS {
        "macos" => "macos",
        "windows" => "windows",
        _ => "linux",
    };
    format!("{os}-{}", std::env::consts::ARCH)
}

fn read_text(path: &Path, limit: u64) -> Result<String, String> {
    let file = fs::File::open(path).map_err(|error| format!("{}: {error}", path.display()))?;
    let mut text = String::new();
    file.take(limit + 1)
        .read_to_string(&mut text)
        .map_err(|error| format!("{}: {error}", path.display()))?;
    if text.len() as u64 > limit {
        return Err(format!("{} exceeds {limit} bytes", path.display()));
    }
    Ok(text)
}

/// The leading placeholder of a command: `pack`, or `runtime.<id>`.
fn placeholder(command: &str) -> Option<&str> {
    command
        .strip_prefix("${")?
        .split_once("}/")
        .map(|(name, _)| name)
}

impl Catalog {
    pub(crate) fn parse(text: &str) -> Result<Self, String> {
        let catalog: Self = toml::from_str(text).map_err(|error| error.to_string())?;
        catalog.validate()?;
        Ok(catalog)
    }

    pub(crate) fn read(file: &Path) -> Result<Self, String> {
        Self::parse(&read_text(file, MAX_CATALOG)?)
    }

    fn validate(&self) -> Result<(), String> {
        let repository: Vec<_> = self.distribution.repository.split('/').collect();
        if self.schema != 1
            || repository.len() != 2
            || !repository.iter().all(|part| {
                !part.is_empty()
                    && *part != "."
                    && *part != ".."
                    && part
                        .bytes()
                        .all(|c| c.is_ascii_alphanumeric() || b"_.-".contains(&c))
            })
            || self.packs.len() > MAX_PACKS
            || self.servers.len() > MAX_SERVERS
        {
            return Err("invalid language server catalog".into());
        }
        for (id, pack) in &self.packs {
            let invalid = |why: &str| Err(format!("invalid language server pack {id}: {why}"));
            if !is_server_name(id) {
                return invalid("the id is not a pack name");
            }
            if pack.version.trim().is_empty() || pack.license.trim().is_empty() {
                return invalid("version and license are required");
            }
            for requirement in &pack.requires {
                let Some((required, major)) = requirement.split_once('@') else {
                    return invalid(&format!("requirement {requirement} is not id@major"));
                };
                let provided = self
                    .packs
                    .get(required)
                    .is_some_and(|other| other.version.split('.').next() == Some(major));
                if !provided {
                    return invalid(&format!("{requirement} is not provided by the catalog"));
                }
            }
            let any = pack.platforms.contains_key("any");
            if pack.platforms.is_empty() || (any && pack.platforms.len() != 1) {
                return invalid("a pack has either the platform any or specific platforms");
            }
            for (platform, archive) in &pack.platforms {
                let release = archive
                    .release
                    .strip_prefix("lsp-servers-")
                    .unwrap_or_default();
                if platform != "any" && !PLATFORMS.contains(&platform.as_str()) {
                    return invalid(&format!("unknown platform {platform}"));
                }
                if archive.asset != format!("{id}-{platform}.tar.gz") {
                    return invalid(&format!("the {platform} archive has an unexpected name"));
                }
                if release.is_empty()
                    || !release
                        .bytes()
                        .all(|c| c.is_ascii_alphanumeric() || b"_.-".contains(&c))
                {
                    return invalid(&format!("the {platform} release tag is invalid"));
                }
                if archive.sha256.len() != 64
                    || !archive
                        .sha256
                        .bytes()
                        .all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
                {
                    return invalid(&format!("the {platform} digest is not a SHA-256"));
                }
                if archive.size == 0 || archive.size > MAX_ARCHIVE {
                    return invalid(&format!("the {platform} archive size is out of range"));
                }
            }
        }
        for (id, entry) in &self.servers {
            let invalid =
                |why: &str| Err(format!("invalid language server catalog entry {id}: {why}"));
            if !is_server_name(id) {
                return invalid("the id is not a server name");
            }
            if entry.name.trim().is_empty() {
                return invalid("a name is required");
            }
            let Some(pack) = self.packs.get(&entry.pack) else {
                return invalid(&format!("the pack {} is not in the catalog", entry.pack));
            };
            // A command never names a program that would be looked up on PATH.
            match placeholder(&entry.command) {
                Some("pack") => {}
                Some(runtime)
                    if runtime.strip_prefix("runtime.").is_some_and(|runtime| {
                        pack.requires
                            .iter()
                            .any(|r| r.split('@').next() == Some(runtime))
                    }) => {}
                _ => {
                    return invalid(
                        "the command must start with ${pack}/ or the ${runtime.<id>}/ of a required pack",
                    );
                }
            }
        }
        Ok(())
    }

    /// The packs a pack needs installed, by id.
    pub(crate) fn requires(&self, pack: &str) -> Vec<String> {
        self.packs.get(pack).map_or_else(Vec::new, |pack| {
            pack.requires
                .iter()
                .filter_map(|requirement| requirement.split('@').next())
                .map(str::to_owned)
                .collect()
        })
    }

    /// The pinned archive of `pack` for `platform`, or why there is none.
    pub(crate) fn archive(&self, pack: &str, platform: &str) -> Result<PackArchive, String> {
        let entry = self
            .packs
            .get(pack)
            .ok_or_else(|| format!("the catalog has no pack {pack}"))?;
        let archive = entry
            .platforms
            .get(platform)
            .or_else(|| entry.platforms.get("any"))
            .ok_or_else(|| format!("{pack} is not available for {platform}"))?;
        Ok(PackArchive {
            version: entry.version.clone(),
            url: format!(
                "https://github.com/{}/releases/download/{}/{}",
                self.distribution.repository, archive.release, archive.asset
            ),
            sha256: archive.sha256.clone(),
            size: archive.size,
        })
    }

    /// How each server of `pack` is started, with placeholders still in place.
    pub(crate) fn launches(&self, pack: &str) -> Vec<Launching> {
        self.servers
            .iter()
            .filter(|(_, entry)| entry.pack == pack)
            .map(|(id, entry)| Launching {
                server: id.clone(),
                command: entry.command.clone(),
                args: entry.args.clone(),
                options: entry
                    .initialization_options
                    .as_ref()
                    .and_then(|options| serde_json::to_value(options).ok()),
            })
            .collect()
    }

    pub(crate) fn pack_ids(&self) -> impl Iterator<Item = &str> {
        self.packs.keys().map(String::as_str)
    }

    /// The servers the language service runs, as it reads them.
    pub(crate) fn servers(&self) -> Result<ServerSet, String> {
        let sources = self
            .servers
            .iter()
            .map(|(id, entry)| {
                let mut root = json!({
                    "markers": entry.root.markers,
                    "fallback": entry.root.fallback,
                });
                if let Some(strategy) = &entry.root.strategy {
                    root["strategy"] = json!(strategy);
                }
                let languages: Vec<Value> = entry
                    .languages
                    .iter()
                    .map(|binding| {
                        let mut value = json!({
                            "language": binding.language,
                            "language_id": binding.language_id,
                        });
                        if let Some(variant) = &binding.variant {
                            value["variant"] = json!(variant);
                        }
                        value
                    })
                    .collect();
                let mut definition = json!({
                    "name": id,
                    "display_name": entry.name,
                    "command": entry.command,
                    "args": entry.args,
                    "priority": entry.priority,
                    "pack": entry.pack,
                    "root": root,
                    "languages": languages,
                });
                if let Some(options) = &entry.initialization_options {
                    definition["initialization_options"] =
                        serde_json::to_value(options).map_err(|error| error.to_string())?;
                }
                Ok((id.clone(), definition.to_string()))
            })
            .collect::<Result<Vec<_>, String>>()?;
        let borrowed: Vec<(&str, &str)> = sources
            .iter()
            .map(|(id, json)| (id.as_str(), json.as_str()))
            .collect();
        ServerSet::from_sources(&borrowed)
    }
}

/// The server set a catalog file describes. A missing file is no servers.
pub(crate) fn load(file: &Path) -> Result<ServerSet, String> {
    match fs::metadata(file) {
        Ok(_) => Catalog::read(file)?.servers(),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(ServerSet::default()),
        Err(error) => Err(format!("{}: {error}", file.display())),
    }
}

/// Where the catalog is staged: beside the language packages.
fn catalog_file(executable: &Path) -> PathBuf {
    super::language_packs::bundled_directory(executable, "lsp-servers").join("lsp-servers.toml")
}

static INSTALLER: OnceLock<Option<Arc<super::lsp_install::Installer>>> = OnceLock::new();

/// The installer for the catalog's packs; `None` before `initialize`, when the
/// catalog holds no packs, or when there is nowhere to install to.
pub(crate) fn installer() -> Option<Arc<super::lsp_install::Installer>> {
    INSTALLER.get().cloned().flatten()
}

/// Reads the catalog beside the executable and installs its servers for the
/// process. A catalog that cannot be read is reported and leaves no servers.
pub(crate) fn initialize() {
    #[cfg(not(test))]
    let catalog = {
        let executable = std::env::current_exe().expect("locate Loom language server catalog");
        let file = catalog_file(&executable);
        match fs::metadata(&file) {
            Ok(_) => Catalog::read(&file)
                .and_then(|catalog| catalog.servers().map(|set| (catalog, set)))
                .map_err(|error| eprintln!("language servers: {error}"))
                .ok(),
            Err(_) => None,
        }
    };
    #[cfg(test)]
    let catalog: Option<(Catalog, ServerSet)> = None;
    let (set, installer) = match catalog {
        Some((catalog, set)) => (
            set,
            super::lsp_install::Installer::production(Arc::new(catalog)),
        ),
        None => (ServerSet::default(), None),
    };
    let _ = INSTALLER.set(installer);
    if let Err(error) = ServerSet::install(set) {
        eprintln!("language servers: {error}");
    }
}

